  ui_story_30460201_21_dialog_content = "...",
  ui_story_30460201_22_dialog_content = "¿Hicieron una broma y luego se atreven a preguntar si estoy molesto?",
  ui_story_30460201_23_dialog_content = "¿Molesto? Ya que estás aquí, ¿por qué no apaciguan su enojo?",
  ui_story_30460201_24_dialog_content = "Joven, eres el maestro del Colossus. Este es tu territorio, tu deberías decidir.",
  ui_story_30460201_25_dialog_content = "Yo se. En ese caso, ¿puedo hacer un registro de esto?",
  ui_story_30460201_26_dialog_content = "Solo quiero guardar un registro de todos los mayores incidentes que se han dado en el Colossus.",
  ui_story_30460201_27_dialog_content = "¿Un registro especial exclusivo para el Colossus? Bien, tienes mi permiso.",
  ui_story_30460201_28_dialog_content = "<size=70>Noticias Colossus<</size>",
  ui_story_30460201_29_dialog_content = "El<color=#FFB400>Incidente de la Flor de Keating</color> tuvo lugar hoy en el Colossus. Miremos más de cerca.",
  ui_story_30460201_30_dialog_content = "Esto es basado en la escena y la narración de Schwartz el Señor de la Ciudad.",
  ui_story_30460201_31_dialog_content = "Podemos ver que claramente sospecha del cuarteto de Keating.",
  ui_story_30460201_32_dialog_content = "Tú... Esta es una forma bastante especial de grabar cosas.",
  ui_story_30460201_33_dialog_content = "Ejem, Vice y yo pensamos en esto...",
  ui_story_30460201_34_dialog_content = "Se nos ocurrió este nuevo método de grabación después de referirnos a muchas fuentes de información, y actualmente lo estamos probando.",
  ui_story_30460201_35_dialog_content = "Todos los registros de incidentes se adjuntarán con explicaciones detalladas y animadas, haciéndolos precisos y fáciles de leer.",
  ui_story_30460201_36_dialog_content = "PlayerName♪ no estás dejando hablar a Keating♪",
  ui_story_30460201_37_dialog_content = "¿Intentas excluirnos? ¿Solo quieres jugar con el Señor de la Ciudad?",
  ui_story_30460201_38_dialog_content = "Lo siento, solo déjenme hacer un registro descriptivo.",
  ui_story_30460201_39_dialog_content = "Comencemos entonces. Haré que hablen pronto.",
  ui_story_30460201_40_dialog_content = "Para este registro, deberán <color=#FFB400>poner atención a la formalidad de sus palabras y el efecto de visualización.</color>",
  ui_story_30460201_41_dialog_content = "Esa explicación es suficiente. Solo empieza...",
  ui_story_30460201_42_dialog_content = "De hecho, la parte sospechada por el demandante parece no estar satisfecha con su conclusión.",
  ui_story_30460201_43_dialog_content = "¿Quién? ¿Qué?",
  ui_story_30460201_44_dialog_content = "Sí, lo hicieron. Pusiste esta flor detrás de mi oreja mientras descansaba.",
  ui_story_30460201_45_dialog_content = "Eso es un malentendido.",
  ui_story_30460201_46_dialog_content = "Estás molesto porque confundiste la flor con una broma.",
  ui_story_30460201_47_dialog_content = "Pero no deberías estar molesto.",
  ui_story_30460201_48_dialog_content = "¿Por qué?",
  ui_story_30460201_49_dialog_content = "Porque la ofrenda de una flor representa respeto.",
  ui_story_30460201_50_dialog_content = "Eso es lo que nos enseñó <color=#FFB400>Uriah</color>.",
  ui_story_30460201_51_dialog_content = "Lo siento, tengo que interrumpirte. ¿Puedo hacer unas preguntas?",
  ui_story_30460201_52_dialog_content = "Lo pondré todo en las notas del registro.",
  ui_story_30460201_53_dialog_content = "PlayerName, ¿quieres hacer una pregunta? Pregunta♪",
  ui_story_30460201_54_option_content = "Pregunta por la flor.",
  ui_story_30460201_55_dialog_content = "¿Cómo conseguiste esta flor blanca en el Colossus?",
  ui_story_30460201_56_dialog_content = "Aún no sabes, no sabes qué preguntar♪",
  ui_story_30460201_57_dialog_content = "Esta es solo una flor blanca especial que la <color=#FFB400> hermana mayor </color> cultivó con su Lumina. Floreció por la magia de la<color=#FFB400>hermana mayor</color>♪",
  ui_story_30460201_58_dialog_content = "Está bien, lo anotaré.",
  ui_story_30460201_59_option_content = "Pregunta por la hermana mayor.",
  ui_story_30460201_60_dialog_content = "Ella es nuestra querida <color=#FFB400>Uriah</color>, nuestra querida estudiante de la academia♪",
  ui_story_30460201_61_dialog_content = "Ella nos enseñó como hablar, y como cantarle a los nobles♪",
  ui_story_30460201_62_dialog_content = "Esa es información interesante.",
  ui_story_30460201_63_dialog_content = "Ya veo. Lo he anotado.",
  ui_story_30460201_64_dialog_content = "¿También, por qué siento que son algo irrespetuosos con el Señor de la Ciudad?",
  ui_story_30460201_65_dialog_content = "Conflictos como estos pueden agregar drama a los registros.",
  ui_story_30460201_66_dialog_content = "Pero he querido preguntarles por mucho tiempo. La forma en que le hablan al señor de la ciudad...",
  ui_story_30460201_67_option_content = "¿No creen que hay un problema?",
  ui_story_30460201_68_dialog_content = "Tenemos mucho respeto♪ por el Señor de la Ciudad♪",
  ui_story_30460201_69_dialog_content = "Es obvio que lo tratamos diferente comparado a ti, PlayerName♪",
  ui_story_30460201_70_dialog_content = "Jaja, comparado a como tratan a los otros nobles, en verdad son muy educados contigo.",
  ui_story_30460201_71_dialog_content = "Espera, ¿no estaba hablando con el Señor de la Ciudad ahora?",
  ui_story_30460201_72_dialog_content = "¿Por qué siento que soy yo el atacado?",
  ui_story_30460201_73_dialog_content = "Seguro, le agradamos al Señor de la Ciudad y conoce bien nuestras personalidades.",
  ui_story_30460201_74_dialog_content = "Entiendo, entonces así se siente ser respaldado por alguien en el poder...",
  ui_story_30460201_75_option_content = "Señor, ¿le importaría?",
  ui_story_30460201_76_dialog_content = "Son solo palabras descarriadas de varios niños. Naturalmente, no los tomo en serio.",
  ui_story_30460201_77_dialog_content = "El Señor de la Ciudad nos seleccionó.",
  ui_story_30460201_78_dialog_content = "El Señor de la Ciudad sabía como somos y nos permitió unirnos al Coro.",
  ui_story_30460201_79_dialog_content = "¿Es verdad?",
  ui_story_30460201_80_dialog_content = "Desde que tome la decisión, es obvio que su naturaleza sirve un propósito para mí.",
  ui_story_30460201_81_dialog_content = "¡Con razón son incorregibles! Esto debe ser lo que se siente estar respaldado por los poderes...",
  ui_story_30460201_82_dialog_content = "Bien, ya que al Señor de la Ciudad no le molesta, continuaré registrando sus conflictos dramáticos.",
  ui_story_30460201_83_dialog_content = "Continuemos grabando. 3, 2, 1... Acción—",
  ui_story_30460201_84_dialog_content = "¿Así es como ofreces flores? ¿Poniéndolos detrás de las orejas de la gente?",
  ui_story_30460201_85_dialog_content = "Porque es bonito así.",
  ui_story_30460201_86_dialog_content = "Porque es elegante así.",
  ui_story_30460201_87_dialog_content = "Tonterías.",
  ui_story_30460201_88_dialog_content = "Muy bien, porque es cierto.",
  ui_story_30460201_89_dialog_content = "¿Cierto? Es mejor que tengan suficiente evidencia para respaldarlo.",
  ui_story_30460201_90_dialog_content = "La verdad es que nuestra querida hermana Uriah también nos hizo algo similar.",
  ui_story_30460201_91_dialog_content = "Ella nos bendecía con una sonrisa y colocaría una hermosa flor detrás de nuestras orejas.",
  ui_story_30460201_92_dialog_content = "Eso aprendimos. Eso sabemos.",
  ui_story_30460201_93_dialog_content = "Hmph, ¿entonces tienes la intención de responsabilizar a otra persona ahora?",
  ui_story_30460201_94_dialog_content = "Lo siento, déjame interrumpirte. ¿No hay una pequeña superposición con lo que dijiste antes?",
  ui_story_30460201_95_dialog_content = "Querido PlayerName, siempre interrumpes a la gente.",
  ui_story_30460201_96_dialog_content = "El Señor de la Ciudad está ocupado.",
  ui_story_30460201_97_dialog_content = "Se suponía que solo serían pocas preguntas.",
  ui_story_30460201_98_dialog_content = "Pero ahora se han extendido indefinidamente.",
  ui_story_30460201_99_dialog_content = "Se ha vuelto un mayor problema♪",
  ui_story_30460201_100_dialog_content = "No me importa, pero debería tomar nota de esto. Mi tiempo es limitado, así que terminemos esto.",
  ui_story_30460201_101_dialog_content = "Disculpa, lo editaré después de grabar las cosas que decimos. Por favor digan algo en conclusión.",
  ui_story_30460201_102_dialog_content = "3, 2, 1... Acción—",
  ui_story_30460201_103_dialog_content = "No eludimos nuestras responsabilidades—solo decimos la verdad.",
  ui_story_30460201_104_dialog_content = "Además, solo somos niños. ¿Por qué te preocupas por eso?",
  ui_story_30460201_105_dialog_content = "Son niños, pero deben darles una lección cuando es necesario.",
  ui_story_30460201_106_dialog_content = "Los niños no deben ser malcriados.",
  ui_story_30460201_107_dialog_content = "En cuanto ahora, la situación es clara.",
  ui_story_30460201_108_dialog_content = "Aunque los chicos de Keating afirmaron que nunca habían hecho bromas...",
  ui_story_30460201_109_dialog_content = "Lord Schwartz tiene la intención de responsabilizarlos después de esto.",
  ui_story_30460201_110_dialog_content = "Este es el reporte de registro preparado por PlayerName, reportero del Colossus.",
  ui_story_30460201_111_dialog_content = "Navegador: PlayerName\nReportero en el lugar: PlayerName\nPersonas presentes: Niel, de la Keating Coro\n Cara, de la Keating Coro\n Pedro, de la Keating Coro\n Diana, de la Keating Coro\n Caballero Schwartz, Señor de la ciudad de Lumopolis",
  ui_story_30460201_112_dialog_content = "Qué interesante. Este reporte no está nada mal.",
  ui_story_30460201_113_dialog_content = "Gracias por su apoyo, Señor de la Ciudad. Tu discurso fue perfecto.",
  ui_story_30460201_114_dialog_content = "Aunque el incidente se registra de manera diferente a los de Lumopolis, no debes preocuparte porque puedo entenderlo.",
  ui_story_30460201_115_dialog_content = "Ese es el fin de este asunto. Tengo otras cosas que atender.",
  ui_story_30460201_116_dialog_content = "Cuídese, señor de la Ciudad.",
  ui_story_30460201_117_dialog_content = "PlayerName, nos ignoras y solo hablas con el Señor de la Ciudad de nuevo.",
  ui_story_30460201_118_dialog_content = "PlayerName intenta ser respetuoso,",
  ui_story_30460201_119_dialog_content = "pero tiene una extraña elección de palabras.",
  ui_story_30460201_120_dialog_content = "Fue un fracaso.",
  ui_story_30460201_121_dialog_content = "Deberías ser un poco más comprensivo ya que incluso el Señor de la Ciudad no dijo nada.",
  ui_story_30460201_122_dialog_content = "No he aprendido nada de etiqueta de corte, así que ya intento ser lo más respetuoso.",
  ui_story_30460201_123_dialog_content = "También se grabó que el señor de la ciudad dijo que no los malcriara.",
  ui_story_30460201_124_dialog_content = "Pero siento que aún es muy tolerante con ustedes.",
  ui_story_30460201_125_dialog_content = "Sin duda.",
  ui_story_30460601_1_dialog_content = "\"En el momento en que abres este Tomo de Magia Negra\",",
  ui_story_30460601_2_dialog_content = "\"Serás transportado a un mundo nuevo y misterioso\".",
  ui_story_30460601_3_dialog_content = "\"Un mundo de maravillas y magia\"",
  ui_story_30460601_4_dialog_content = "\"Lleno de todo tipo de cosas extraordinarias\".",
  ui_story_30460601_5_dialog_content = "\"Un mundo para almas curiosas y solitarias\".",
  ui_story_30460601_6_dialog_content = "¿Qué opinas? La introducción de este libro realmente sabe cómo captar la atención del lector, ¿no?",
  ui_story_30460601_7_dialog_content = "¿Es este \"Tomo de Magia Negra\" también la razón por la que están vestidos así?",
  ui_story_30460601_8_dialog_content = "Puedo asegurarte, mi amigo ignorante y adulto, que este libro contiene magia negra real y prohibida.",
  ui_story_30460601_9_dialog_content = "¿Y dices que una mujer extraña en la calle te dio esto?",
  ui_story_30460601_10_dialog_content = "¿Estás seguro de que no estaba mintiendo?",
  ui_story_30460601_11_dialog_content = "A diferencia de ti, no somos tan fáciles de engañar.",
  ui_story_30460601_12_dialog_content = "¡Siguió hablando y hablando de lo aterrador que es el libro!",
  ui_story_30460601_13_dialog_content = "Estoy seguro de que solo estaba haciendo eso para llamar tu atención.",
  ui_story_30460601_14_dialog_content = "También dijo que este libro solo es aterrador para adultos. ¡Para los niños pequeños como nosotros, es perfectamente seguro!",
  ui_story_30460601_15_dialog_content = "¿Estás bromeando no? ¡Obviamente te estaba engañando para que compraras este libro!",
  ui_story_30460601_16_dialog_content = "¿Cuánto le pagaste? ¡Vamos, te ayudaré a recuperar tu dinero!",
  ui_story_30460601_17_dialog_content = "Ella no quería nuestro dinero.",
  ui_story_30460601_18_dialog_content = "¿Eh? Entonces era gratis...",
  ui_story_30460601_19_dialog_content = "¿Crees que todavía hay un problema ahora?",
  ui_story_30460601_20_option_content = "Si fuera gratis, supongo que no.",
  ui_story_30460601_21_dialog_content = "♫¡La frugalidad es una mentira que los adultos esconden, la horrible avaricia que guardan dentro!♪",
  ui_story_30460601_22_dialog_content = "¡Solo lo guardo por curiosidad!",
  ui_story_30460601_23_option_content = "Además, nada en la vida es gratis, ¿sabes?",
  ui_story_30460601_24_dialog_content = "♫ ¡Y así, al final del día, el dinero todavía gobierna todos los juegos que juegan! ♪",
  ui_story_30460601_25_dialog_content = "Sí, sí, siéntete libre de pensar lo que quieras.",
  ui_story_30460601_26_dialog_content = "Entonces, ¿qué tipo de libro es este, de todos modos?",
  ui_story_30460601_27_dialog_content = "Supongo que no estaría de más dejarte echar un vistazo.",
  ui_story_30460601_28_dialog_content = "En todo caso, usted podría ser capaz de ayudar.",
  ui_story_30460601_29_dialog_content = "Es un antiguo libro de magia prohibida. La mayor parte ya se ha perdido.",
  ui_story_30460601_30_dialog_content = "Pero en la última página...",
  ui_story_30460601_31_dialog_content = "\"Nombre: Monstruo del Titanic...\"",
  ui_story_30460601_32_dialog_content = "(Huh, el resto está más allá del reconocimiento).",
  ui_story_30460601_33_dialog_content = "Materiales: melón amargo, apio, pimiento verde...",
  ui_story_30460601_34_dialog_content = "¡Espera, estos son solo ingredientes de cocina comunes!",
  ui_story_30460601_35_dialog_content = "Es posible que desee echar un vistazo a la siguiente línea.",
  ui_story_30460601_36_dialog_content = "Tentáculos coleoides, moco de oruga de Koppia, aletas de caballa.",
  ui_story_30460601_37_dialog_content = "Uhh... ¿Qué diablos son estas cosas?",
  ui_story_30460601_38_dialog_content = "Al parecer, algunos ingredientes carnosos y pegajosos de orígenes desconocidos.",
  ui_story_30460601_39_dialog_content = "Ahora, ¿crees que este libro está lleno de magia negra?",
  ui_story_30460601_40_dialog_content = "(Estoy bastante seguro de que es solo una receta extraña, pero probablemente les asuste a los niños pequeños como ellos. Tal vez debería seguirles el juego por ahora...)",
  ui_story_30460601_41_dialog_content = "Es cierto, hay algo aterrador en los materiales enumerados aquí...",
  ui_story_30460601_42_dialog_content = "Solo leerlos en voz alta te da escalofríos.",
  ui_story_30460601_43_dialog_content = "He aquí, esta es la legendaria Caelestita. ¡Qué \"legendario\" eres!",
  ui_story_30460601_44_dialog_content = "No bromearía demasiado, muchachos. ¿Qué pasa si este hechizo realmente puede convocar a un monstruo grande y horrible?",
  ui_story_30460601_45_dialog_content = "¡Eso sería fantástico!",
  ui_story_30460601_46_dialog_content = "¡Dividámonos y busquemos esos ingredientes!",
  ui_story_30460601_47_dialog_content = "¡Muévanse todos!",
  ui_story_30460601_48_dialog_content = "Espera, ¿hablas en serio con esto?",
  ui_story_30460601_49_dialog_content = "Pero que si...",
  ui_story_30460601_50_dialog_content = "Los cobardes están condenados a esconderse tras bambalinas.",
  ui_story_30460601_51_dialog_content = "¡Solo los valientes son bendecidos con milagros!",
  ui_story_30460601_52_dialog_content = "(Es bastante fácil para ti decirlo, pero no podré quedarme quieto si algo realmente sucede).",
  ui_story_30460601_53_dialog_content = "Si quiere probarse a sí mismo, debe proporcionarnos un lugar para mezclar estos ingredientes.",
  ui_story_30460601_54_dialog_content = "¿Eh? ¿Por qué yo?",
  ui_story_30460601_55_dialog_content = "(Je, ¡sabía que me necesitaban! ¡Adelante, dime lo importante que soy!)",
  ui_story_30460601_56_dialog_content = "Porque si no ayudas, no tendremos más remedio que usar la poción contigo.",
  ui_story_30460601_57_dialog_content = "Quién sabe, ¡quizás incluso te despiertes con un monstruo gigantesco en tu habitación!",
  ui_story_30460601_58_dialog_content = "¡¿Así que ahora me estás amenazando?!",
  ui_story_30460601_59_dialog_content = "¿Creo que los adultos llaman a esto \"quid pro quo\"?",
  ui_story_30460601_60_dialog_content = "¡No se limite a lanzar palabras cuando en realidad no sabe lo que significan!",
  ui_story_30460601_61_dialog_content = "(Planeaba ayudarlos desde el principio, pero ahora parece que me veo obligado a hacerlo...)",
  ui_story_30460601_62_dialog_content = "Hay una olla grande en la cocina. Puedes usarlo como tu \"caldero\".",
  ui_story_30460601_63_dialog_content = "Sobreestimas gravemente la resistencia de tus utensilios de cocina.",
  ui_story_30460601_64_dialog_content = "Además, no queremos dañar el Coloso de ninguna manera.",
  ui_story_30460601_65_dialog_content = "¿Estáis absolutamente seguros de que queréis crear un monstruo gigante?",
  ui_story_30460601_66_dialog_content = "¡Por supuesto que somos! ¿Cómo podría estar volando un águila sin que rugiera su ambición?",
  ui_story_30460601_67_dialog_content = "Bien, entonces iré a preguntar. Carleen si hay laboratorios abandonados en Lumopolis para su uso.",
  ui_story_30460601_68_dialog_content = "Si bien no tenemos mucha confianza en su capacidad para hacer las cosas...",
  ui_story_30460601_69_dialog_content = "con dama Carleen por nuestra parte, ¡no deberíamos tener nada de qué preocuparnos!",
  ui_story_30460601_70_dialog_content = "Ahora, ¡manos a la obra!",
  ui_story_30460601_71_dialog_content = "¡Nos vemos luego!",
  ui_story_30460601_72_dialog_content = "¿Te escuché bien, cariño? ¿Quieres melón amargo, apio y pimientos verdes?",
  ui_story_30460601_73_dialog_content = "Pensé que siempre odiaste estas cosas.",
  ui_story_30460601_74_dialog_content = "Tienes toda la razón, mi querida madre.",
  ui_story_30460601_75_dialog_content = "¡Y sin embargo, aquí estás pidiendo esos vegetales saludables! ¡Mamá no podría estar más orgullosa de ti, Niel!",
  ui_story_30460601_76_dialog_content = "Dejaré que el personal de la cocina te prepare una bolsa grande ahora mismo, ¿de acuerdo?",
  ui_story_30460601_77_dialog_content = "Gracias mamá. Por favor, no agregue nada más, tampoco.",
  ui_story_30460601_78_dialog_content = "¡Mi pequeño Niel finalmente está aprendiendo a comer sus vegetales! ¡Estoy tan feliz!",
  ui_story_30460601_79_dialog_content = "¿Es suficiente?",
  ui_story_30460601_80_dialog_content = "Sí mamá. Ahora, debería irme antes de que tus lágrimas comiencen a inundar la casa.",
  ui_story_30460601_81_dialog_content = "Antes de que te vayas, deja que el chef te cocine algo. ¿Qué te parece melón amargo relleno de apio más un plato de pimientos verdes fritos con perejil?",
  ui_story_30460601_82_dialog_content = "¡Quiero ver cómo te lo comes todo!",
  ui_story_30460601_83_dialog_content = "Agradezco la preocupación, pero no tengo mucha hambre en este momento, mamá.",
  ui_story_30460601_84_dialog_content = "¡Pero te ayudará a crecer grande y fuerte! ¡Prueba un bocado!",
  ui_story_30460601_85_dialog_content = "¡Te dejaré disfrutar de esta deliciosa y nutritiva comida, mamá! ¡Realmente, realmente tengo que irme ahora! ¡Adiós!",
  ui_story_30460601_86_dialog_content = "¡Vaya, se escapó tan rápido! ¡Mi pequeño Niel debe estar comiendo sus verduras, después de todo!",
  ui_story_30460601_87_dialog_content = "Ok, eso lo resuelve! A partir de ahora, ¡todas las comidas de esta casa deben incluir estas verduras!",
  ui_story_30460601_88_dialog_content = "He buscado en todos los libros, ¡pero todavía nada!",
  ui_story_30460601_89_dialog_content = "kara? ¿Estás buscando algo en particular?",
  ui_story_30460601_90_dialog_content = "Sí, profesor. Estoy buscando un libro sobre biología marina.",
  ui_story_30460601_91_dialog_content = "¡Esa es la misma materia que enseño! Jajajaja! ¿Cuándo te interesaste tanto en este campo, Kara?",
  ui_story_30460601_92_dialog_content = "Bueno, estoy tratando de aprender más sobre una criatura llamada \"Coleoid\". Debes saberlo todo, ya que has pasado toda tu vida investigando animales marinos, ¿verdad?",
  ui_story_30460601_93_dialog_content = "De hecho, nadie en la Academia tiene más conocimiento sobre este tema que yo. De hecho, ¡incluso tengo algunos tentáculos coleoides en mi oficina!",
  ui_story_30460601_94_dialog_content = "Seguro que a las personas mayores les encanta inventar historias que nunca existieron cuando eran más jóvenes, ¿no?",
  ui_story_30460601_95_dialog_content = "¡No me estoy inventando nada, Kara! ¡Los tentáculos solo están en mi armario! Si no recuerdo mal, fue hace treinta años que...",
  ui_story_30460601_96_dialog_content = "Si se va a perder en sus recuerdos, profesor. ¿Podrías al menos pasar a la parte importante?",
  ui_story_30460601_97_dialog_content = "Er, muy bien, entonces. En mi juventud, me topé con una hermosa mujer mientras investigaba diferentes especímenes cerca del océano...",
  ui_story_30460601_98_dialog_content = "Déjame adivinar: ¿te enamoraste, pero ella no sintió lo mismo?",
  ui_story_30460601_99_dialog_content = "S-Sí, así es. De todos modos, descubrí una cueva kárstica junto al mar poco después, y en esa cueva...",
  ui_story_30460601_100_dialog_content = "Cuanto más se alargue una historia, peor será el final.",
  ui_story_30460601_101_dialog_content = "¡Me encontré con estos! ¿Ver? ¡Tentáculos coleoides, tal como dije!",
  ui_story_30460601_102_dialog_content = "Y así, el valiente héroe finalmente reclama el tesoro.",
  ui_story_30460601_103_dialog_content = "¡No podría estar mas de acuerdo! Después de todo, yo era un muchacho bastante valiente en mi época...",
  ui_story_30460601_104_dialog_content = "No, no usted profesor. Soy el héroe, y esta es mi recompensa por sentarme a leer tu larga historia.",
  ui_story_30460601_105_dialog_content = "¿eh? ¡P-Pero arriesgué mi vida por estos tentáculos hace treinta años!",
  ui_story_30460601_106_dialog_content = "Lo que significa que ha tenido treinta años para celebrar su logro, entonces, ¿qué más podría desear? A menos, por supuesto, que te lo hayas inventado todo...",
  ui_story_30460601_107_dialog_content = "Te puedo asegurar que mi historia es totalmente cierta. Adelante, tómalos, pero recuerda...",
  ui_story_30460601_108_dialog_content = "Espera, ¿a dónde vas? ¡No había terminado de hablar todavía! Dios mío, ¿qué diablos está tramando esa niña?",
  ui_story_30460601_109_dialog_content = "Discúlpame...",
  ui_story_30460601_110_dialog_content = "¡Bueno, si no es una niña noble de Uptown!",
  ui_story_30460601_111_dialog_content = "Parece que algo anda mal con tus ojos.",
  ui_story_30460601_112_dialog_content = "No estamos acostumbrados a ver gente noble en nuestros mercados, eso es todo.",
  ui_story_30460601_113_dialog_content = "Oh, señorita, usted es muy bonita. ¡Mira tu cabello brillante!",
  ui_story_30460601_114_dialog_content = "Entonces, ¿qué la trae a Lower Lumopolis, señorita? No estás perdido, ¿verdad?",
  ui_story_30460601_115_dialog_content = "Si me dejaras hablar, no tendrías que hacer preguntas tan innecesarias.",
  ui_story_30460601_116_dialog_content = "Necesito aletas de caballa, y las necesito ahora. Por favor.",
  ui_story_30460601_117_dialog_content = "Incluso su voz es bonita, ¿no crees?",
  ui_story_30460601_118_dialog_content = "¡Ahora recuerdo! ella es parte de la Keating ¡Coro!",
  ui_story_30460601_119_dialog_content = "¡Con razón tiene una voz tan melódica!",
  ui_story_30460601_120_dialog_content = "¿En realidad? ¡Pero no escuché lo que dijo hace un momento! ¿Podría decirlo de nuevo, señorita?",
  ui_story_30460601_121_dialog_content = "Provocar al Coro es incurrir en la ira del Dios de la Luz.",
  ui_story_30460601_122_dialog_content = "¡Oh, lo siento mucho! ¡No quise ofenderte!",
  ui_story_30460601_123_dialog_content = "Una edad tan joven para un miembro del coro. ¡Eso es realmente algo para ti!",
  ui_story_30460601_124_dialog_content = "Dedíquense a la Luz, no a sus triviales actividades mortales.",
  ui_story_30460601_125_dialog_content = "Seguro seguro. De todos modos, estas aletas de caballa son bastante raras, pero no tan raras como tener un noble por cliente. ¡Estaré encantada de vendértelos!",
  ui_story_30460601_126_dialog_content = "La Oruga Koppia... De enorme tamaño pero de temperamento gentil, vive en lo profundo de los bosques, particularmente aficionada a dormir.",
  ui_story_30460601_127_dialog_content = "¡Como descendiente de un Caballero, explorar el bosque es solo otra prueba necesaria en mi viaje!",
  ui_story_30460601_128_dialog_content = "Puede que esté solo, pero mientras tenga mi espada, ¡no tengo nada que temer!",
  ui_story_30460601_129_dialog_content = "El suelo es suave y hay un olor inusual en el aire... ¡Ah!",
  ui_story_30460601_130_dialog_content = "Gorjeo, gorgoteo, gorgoteo——",
  ui_story_30460601_131_dialog_content = "(¿Dónde... dónde estoy? Esta respiración cálida y rítmica, y esta sensación de contacto pegajoso...)",
  ui_story_30460601_132_dialog_content = "(Debo estar dentro de la boca de un monstruo gigante... ¡Otra prueba más que superar!)",
  ui_story_30460601_133_dialog_content = "Vaya... Por fin gratis.",
  ui_story_30460601_134_dialog_content = "Qué repugnante... Solo mira toda esta mucosidad. Gracias a Dios que nadie está cerca para verme así.",
  ui_story_30460601_135_dialog_content = "¿Estás bien ahí, pequeña? ¿Qué estás haciendo en el bosque solo?",
  ui_story_30460601_136_dialog_content = "Estoy bien. ¡Mi espada puede atravesar la garganta de cualquier monstruo!",
  ui_story_30460601_137_dialog_content = "Bueno, por lo que sé, tuviste un encontronazo con una Koppia Caterpillar, ¿no?",
  ui_story_30460601_138_dialog_content = "Les gusta enterrarse en el suelo y dormir con la boca abierta. ¿Te caíste en su boca?",
  ui_story_30460601_139_dialog_content = "¡S-Sí, pero solo porque el objetivo de mi prueba era obtener algo de su mucosidad! ¡Eso es todo!",
  ui_story_30460601_140_dialog_content = "¡Oye, cuida tus pasos! No querrás caer en la boca de otro, ¿verdad?",
  ui_story_30460601_141_dialog_content = "Este debe ser el laboratorio mágico abandonado que Carleen me habló de.",
  ui_story_30460601_142_dialog_content = "Es enorme y lejos del camino. Carleen incluso asignó un equipo de soldados para proteger el perímetro.",
  ui_story_30460601_143_dialog_content = "Incluso si algo realmente sucediera, estoy seguro de que podrían manejar las cosas rápidamente.",
  ui_story_30460601_144_dialog_content = "Supongo Carleen realmente debe preocuparse por dejar que esos niños exploren y aprendan.",
  ui_story_30460601_145_dialog_content = "Me pregunto qué diablos se les ocurrirá.",
  ui_story_30460601_146_dialog_content = "♪Los ingredientes han sido reunidos, el momento es ahora.♪",
  ui_story_30460601_147_dialog_content = "♪Mientras el caldero burbujea, ¡lee el conjuro en voz alta!♪",
  ui_story_30460601_148_dialog_content = "♪Llamas parpadeantes y brebaje arremolinado,♪",
  ui_story_30460601_149_dialog_content = "♪¡La verdadera magia no requiere presentación!♪",
  ui_story_30460601_150_dialog_content = "♫May ¡nuestros corazones jóvenes dan nueva vida a este hechizo!♫",
  ui_story_30460601_151_dialog_content = "(Sus ojos brillan mucho. Así deben verse los niños cuando se divierten aprendiendo).",
  ui_story_30460601_152_dialog_content = "¡Tos tos! ¡Tanto humo!",
  ui_story_30460601_153_dialog_content = "¡No es bueno! ¡No puedo ver nada!",
  ui_story_30460601_154_dialog_content = "¡Una sombra! ¡Emergiendo del humo!",
  ui_story_30460601_155_dialog_content = "¡Creo que se está moviendo!",
  ui_story_30460601_156_dialog_content = "¡Oh no, estoy sintiendo una ola de energía muy fuerte! ¡Ponte detrás de mí, muchachos!",
  ui_story_30460601_157_dialog_content = "¿Y qué vas a hacer exactamente TÚ?",
  ui_story_30460601_158_dialog_content = "¿No deberías ser tú el que se esconde detrás de nosotros?",
  ui_story_30460601_159_dialog_content = "Te lo hemos dicho antes, te protegeremos cuando surja la necesidad.",
  ui_story_30460601_160_dialog_content = "Por favor, no te preocupes por nosotros.",
  ui_story_30460601_161_dialog_content = "<color=#e8d9bb>Golpear--</color>",
  ui_story_30460601_162_dialog_content = "¡Qué ruido ensordecedor! ¿Es un demonio mítico o algo así? ¡No, es un eclipse!",
  ui_story_30460601_163_dialog_content = "Por favor, déjanos ir.",
  ui_story_30460601_164_dialog_content = "Por favor, abre los ojos.",
  ui_story_30460601_165_dialog_content = "Eso no es un monstruo en absoluto——",
  ui_story_30460601_166_dialog_content = "Es solo nuestro profesor.",
  ui_story_30460601_167_dialog_content = "¿Qué diablos está pasando aquí?",
  ui_story_30460601_168_dialog_content = "¡¿Un libro de hechizos prohibido de magia negra?! Pensé que Kara estaba actuando extraño hoy, así que decidí seguirla, pero nunca esperé...",
  ui_story_30460601_169_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_30460601_170_dialog_content = "¡Está terminado!",
  ui_story_30460601_171_dialog_content = "¡Ha nacido un milagro!",
  ui_story_30460601_172_dialog_content = "Se ve un poco extraño...",
  ui_story_30460601_173_dialog_content = "Pero también un poco lindo!",
  ui_story_30460601_174_dialog_content = "¿Eso es... un pastel gigante?",
  ui_story_30460601_175_dialog_content = "¡Quedarse atrás! ¡Este pastel sigue siendo obra de magia negra! ¡Lo más probable es que sea venenoso!",
  ui_story_30460601_176_dialog_content = "Mmm, con razón este pastel está prohibido. ¡Es delicioso!",
  ui_story_30460601_177_dialog_content = "¡¿T-Ya le diste un mordisco?! ¡Escúpelo ahora mismo, Kara!",
  ui_story_30460601_178_dialog_content = "Dicen que la delicia está al lado de la piedad, ¿sabes?",
  ui_story_30460601_179_dialog_content = "¿Tú tampoco, Pierre?",
  ui_story_30460601_180_dialog_content = "¡Guau, es realmente delicioso! ¡Pruebe un poco, profesor!",
  ui_story_30460601_181_dialog_content = "Puedo ver a los niños haciendo esto, Sr. Caelestite, ¿pero usted? Por favor, debe detener esta tontería...",
  ui_story_30460601_182_dialog_content = "¡No sabía que el melón amargo y los pimientos verdes se podían usar para hacer algo tan delicioso!",
  ui_story_30460601_183_dialog_content = "¿Melón amargo y pimientos, dices? Bueno, suena lo suficientemente saludable... Ah, al diablo con eso, lo intentaré.",
  ui_story_30460601_184_dialog_content = "¡Mi palabra! ¡Es realmente delicioso!",
  ui_story_30460601_185_dialog_content = "Y con eso, nuestro experimento finalmente ha terminado.",
  ui_story_30460601_186_dialog_content = "¡Creo que no, Diana! Este asunto aún debe ser informado a la Academia.",
  ui_story_30460601_187_dialog_content = "¡Un pastel tan saludable y delicioso debe compartirse con toda la escuela!",
  ui_story_30460601_188_dialog_content = "*Munch* Este pastel es genial y todo...",
  ui_story_30460601_189_dialog_content = "*Munch* Pero todavía hay un pequeño problema.",
  ui_story_30460601_190_dialog_content = "*Munch* Nos engañaron, ¿no?",
  ui_story_30460601_191_dialog_content = "*Munch* Este es claramente un libro de recetas, no un tomo de magia negra.",
  ui_story_30460601_192_dialog_content = "*Munch* ¿Te estás dando cuenta ahora...?",
  ui_story_30460601_193_dialog_content = "Qu... ¿Por qué están tirados en el suelo así? ¿Estás herido?",
  ui_story_30460601_194_dialog_content = "Oh hola Chloe... ¡No, no, no llores! ¡Estamos perfectamente bien!",
  ui_story_30460601_195_dialog_content = "Comimos tanto pastel que no podíamos movernos.",
  ui_story_30460601_196_dialog_content = "Y ahora Chloe el llorón se asustó.",
  ui_story_30460601_197_dialog_content = "Aquí, guardamos un último trozo del pastel.",
  ui_story_30460601_198_dialog_content = "Cometelo. Espero que resuelva tu sentimiento de dolor.",
  ui_story_30460601_199_dialog_content = "¿Hicisteis esta tarta vosotros mismos?",
  ui_story_30460601_200_dialog_content = "¿Ah? ¿Cómo lo supiste?",
  ui_story_30460601_201_dialog_content = "Bueno, parece un poco extraño para ser comprado en una tienda...",
  ui_story_30460601_202_dialog_content = "Supongo que estas en lo correcto. No tengo idea de quién compraría un pastel como este...",
  ui_story_30460601_203_dialog_content = "Parece que el llorón se ha vuelto más perceptivo.",
  ui_story_30460601_204_dialog_content = "Pero aún así, su juicio es difícilmente objetivo.",
  ui_story_30460601_205_dialog_content = "Sí, nuestro pastel tiene un exterior antiestético,",
  ui_story_30460601_206_dialog_content = "¡Pero pronto descubrirás que su sabor es muy superior!",
  ui_story_30460601_207_dialog_content = "Lo siento, sé que no debo juzgar tu pastel por su apariencia. Lo intentaré ahora mismo.",
  ui_story_30460601_208_dialog_content = "¿Cómo es?",
  ui_story_30460601_209_dialog_content = "Sabe muy bien, pero es bastante alta en calorías. Es fácil subir de peso si se come demasiado.",
  ui_story_30460601_210_dialog_content = "Calorías? ¿Ganando peso?",
  ui_story_30460601_211_dialog_content = "Espera, ¿qué dijo de nuevo la señora que nos dio este libro?",
  ui_story_30460601_212_dialog_content = "\"Este libro solo es aterrador para los adultos. ¡Para los niños pequeños como nosotros, es perfectamente seguro!\"",
  ui_story_30460601_213_dialog_content = "Así que la parte \"aterradora\"... ¿Era la cantidad de calorías en el pastel?",
  ui_story_30460601_214_dialog_content = "...Nos han engañado..."
}
return config
